from datetime import date; from decimal import Decimal; from unittest.mock import AsyncMock, MagicMock; from uuid import uuid4; import pytest; from src.extraction import TransactionDirection; from src.extraction.orm.layer2 import AtomicTransaction; from src.reconciliation.extension.anomaly import detect_anomalies
@pytest.fixture
def db_engine(): return MagicMock()
async def test_detect_large_amount_anomaly(): db = AsyncMock(); user_id = uuid4(); txn = AtomicTransaction(id=uuid4(), user_id=user_id, txn_date=date(2023, 1, 1), amount=Decimal('1000'), direction=TransactionDirection.OUT, description='Generic Transaction', currency='SGD', dedup_hash=uuid4().hex, source_documents=[{'doc_id': str(uuid4()), 'doc_type': 'bank_statement'}]); mock_result_avg = MagicMock(); mock_result_avg.scalar_one_or_none.return_value = 10; mock_result_daily = MagicMock(); mock_result_daily.scalar_one_or_none.return_value = 1; mock_result_history = MagicMock(); mock_result_history.scalar_one_or_none.return_value = 10; db.execute.side_effect = [mock_result_avg, mock_result_daily, mock_result_history]; anomalies = await detect_anomalies(db, txn, user_id=user_id); assert any((a.anomaly_type == 'LARGE_AMOUNT' for a in anomalies)); assert not any((a.anomaly_type == 'NEW_MERCHANT' for a in anomalies)); _m1_db = AsyncMock(); _m1_user_id = uuid4(); _m1_txn = AtomicTransaction(id=uuid4(), user_id=_m1_user_id, txn_date=date(2023, 1, 1), amount=Decimal('10'), direction=TransactionDirection.OUT, description='New Merchant', currency='SGD', dedup_hash=uuid4().hex, source_documents=[{'doc_id': str(uuid4()), 'doc_type': 'bank_statement'}]); _m1_mock_result_avg = MagicMock(); _m1_mock_result_avg.scalar_one_or_none.return_value = 10; _m1_mock_result_daily = MagicMock(); _m1_mock_result_daily.scalar_one_or_none.return_value = 1; _m1_mock_result_history = MagicMock(); _m1_mock_result_history.scalar_one_or_none.return_value = 0; _m1_db.execute.side_effect = [_m1_mock_result_avg, _m1_mock_result_daily, _m1_mock_result_history]; _m1_anomalies = await detect_anomalies(_m1_db, _m1_txn, user_id=_m1_user_id); assert any((_m1_a.anomaly_type == 'NEW_MERCHANT' for _m1_a in _m1_anomalies)); _m2_db = AsyncMock(); _m2_user_id = uuid4(); _m2_txn = AtomicTransaction(id=uuid4(), user_id=_m2_user_id, txn_date=date(2023, 1, 1), amount=Decimal('10'), direction=TransactionDirection.OUT, description='Spam Merchant', currency='SGD', dedup_hash=uuid4().hex, source_documents=[{'doc_id': str(uuid4()), 'doc_type': 'bank_statement'}]); _m2_mock_result_avg = MagicMock(); _m2_mock_result_avg.scalar_one_or_none.return_value = 10; _m2_mock_result_daily = MagicMock(); _m2_mock_result_daily.scalar_one_or_none.return_value = 6; _m2_mock_result_history = MagicMock(); _m2_mock_result_history.scalar_one_or_none.return_value = 10; _m2_db.execute.side_effect = [_m2_mock_result_avg, _m2_mock_result_daily, _m2_mock_result_history]; _m2_anomalies = await detect_anomalies(_m2_db, _m2_txn, user_id=_m2_user_id); assert any((_m2_a.anomaly_type == 'FREQUENCY_SPIKE' for _m2_a in _m2_anomalies))
